import java.util.*;
import java.io.*;

public class VariantFour {
    public static void main(String[] args) throws Exception {
        new VariantFour().process();
    }

    public void process() throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        long k = sc.nextLong();
        final long MOD = 998244353;

        if (k >= n) {
            pw.println(0);
            pw.flush();
            return;
        }

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
            invFact[i] = modularInverse(fact[i], MOD);
        }

        int r = (int) (n - k);
        long sumWays = 0;

        for (int i = 1; i <= r; i++) {
            long term = fact[r] * invFact[r - i] % MOD;
            term = term * invFact[i] % MOD;
            term = term * pow(i, n, MOD) % MOD;
            if ((r - i) % 2 == 1) {
                term = -term;
            }
            sumWays = (sumWays + term + MOD) % MOD;
        }

        long answer;
        if (k == 0) {
            answer = sumWays * fact[n] % MOD;
            answer = answer * invFact[r] % MOD;
            answer = answer * invFact[n - r] % MOD;
        } else {
            answer = 2 * sumWays % MOD;
            answer = answer * fact[n] % MOD;
            answer = answer * invFact[r] % MOD;
            answer = answer * invFact[n - r] % MOD;
        }
        pw.println(answer);
        pw.flush();
    }

    private long pow(long base, int exp, long mod) {
        long result = 1;
        long cur = base % mod;
        for (int i = 0; i < exp; i++) {
            result = (result * cur) % mod;
        }
        return result;
    }

    private long modularInverse(long a, long m) {
        return pow(a, (int) m - 2, m);
    }
}
